from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable tile size for the inner j loop. Adjust this constant to
# match the cache and vector-width characteristics of the target CPU.
J_TILE = 32


@proc
def kernel_mvt_base(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Fused matrix–vector operations:
    #   x1[i] += sum_j A[i, j] * y_1[j]
    #   x2[j] += sum_i A[i, j] * y_2[i]
    #
    # This is algebraically equivalent to the original PolyBench MVT
    # formulation but traverses A row-major only, improving cache
    # locality for A, y_1, and y_2.
    for i in seq(0, n):
        for j in seq(0, n):
            x1[i] += A[i, j] * y_1[j]
            x2[j] += A[i, j] * y_2[i]


# Apply locality- and ILP-oriented scheduling to the baseline kernel.

kernel_mvt_opt = kernel_mvt_base

# Tile the inner j loop so that the working set of A[i, j] and y_1[j] /
# y_2[i] for each tile fits better in cache, and to expose a fixed-size
# inner loop amenable to aggressive unrolling or vectorization.
kernel_mvt_opt = divide_loop(kernel_mvt_opt, "j", J_TILE, ["jo", "ji"], tail="guard")

# Unroll the main tiled j-loop body (the first 'ji' loop with constant
# trip count J_TILE). Any remainder loop created by divide_loop keeps a
# dynamic bound and is left rolled.
kernel_mvt_opt = unroll_loop(kernel_mvt_opt, "ji #0")

# Export the optimized version under the externally visible name that
# the C driver expects.
kernel_mvt = rename(kernel_mvt_opt, "kernel_mvt")
