from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline mathematical specification: identical to the original PolyBench
# kernel. We keep this simple and then apply scheduling primitives below.
@proc
def kernel_mvt_base(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # First matrix-vector product: x1[i] += sum_j A[i,j] * y_1[j]
    for i in seq(0, n):
        for j in seq(0, n):
            x1[i] = x1[i] + A[i, j] * y_1[j]

    # Second matrix-vector product: x2[i] += sum_j A[j,i] * y_2[j]
    for i in seq(0, n):
        for j in seq(0, n):
            x2[i] = x2[i] + A[j, i] * y_2[j]


# Start scheduling from the baseline specification.
kernel_mvt_opt = kernel_mvt_base

# -------------------------------------------------------------------------
# 1) Parallelize the outer i-loop of the first matrix-vector product.
#    Each iteration of this loop updates a distinct x1[i], so it is
#    safe to parallelize. The backend will typically lower this to
#    an OpenMP parallel for.
# -------------------------------------------------------------------------
kernel_mvt_opt = parallelize_loop(kernel_mvt_opt, "i #0")

# -------------------------------------------------------------------------
# 2) Tile the j-loop of the first matrix-vector product.
#
#    This improves cache locality for:
#      - A[i, j]  : we sweep j in contiguous chunks,
#      - y_1[j]   : reused within each tile.
#
#    We use a tunable constant TILE_J; changing it allows adapting
#    to different cache hierarchies without modifying the algorithm.
# -------------------------------------------------------------------------
TILE_J = 64
kernel_mvt_opt = divide_loop(kernel_mvt_opt, "j #0", TILE_J, ["jo", "ji"], tail="guard")

# After this transformation, the first MVT looks conceptually like:
#   for i in 0..n:
#     for jo in 0..ceil(n/TILE_J):
#       for ji in 0..TILE_J:
#         j = jo*TILE_J + ji
#         if j < n: x1[i] += A[i,j] * y_1[j]
# which preserves the original semantics for all n.

# -------------------------------------------------------------------------
# 3) Improve locality of the second matrix-vector product.
#
#    Original:
#       for i in 0..n:
#         for j in 0..n:
#           x2[i] += A[j,i] * y_2[j]
#
#    A is stored row-major as A[row, col]. The access A[j, i] with
#    inner j walks a column with a large stride. We reorder the loops
#    so that j becomes the outer loop and i the inner loop:
#
#       for j in 0..n:
#         for i in 0..n:
#           x2[i] += A[j,i] * y_2[j]
#
#    For each fixed j we now traverse row j of A contiguously in i,
#    and reuse y_2[j] across the inner loop. The order of updates to
#    each x2[i] with respect to j is unchanged, so the computation is
#    mathematically identical.
#
#    After step (2), the only consecutive (i, j) loop pair in the
#    procedure is the second matrix-vector product, so the shorthand
#    pattern "i j" uniquely identifies it.
# -------------------------------------------------------------------------
kernel_mvt_opt = reorder_loops(kernel_mvt_opt, "i j")

# -------------------------------------------------------------------------
# 4) Tile the inner i-loop of the second matrix-vector product.
#
#    After reordering, we have:
#       for j in 0..n:
#         for i in 0..n:
#           x2[i] += A[j,i] * y_2[j]
#
#    We tile the i-loop to operate on contiguous blocks of x2 and
#    A[j, :] at a time. This exposes a unit-stride inner loop that
#    the C compiler can vectorize effectively.
#
#    TILE_I is another tunable constant controlling the tile size.
# -------------------------------------------------------------------------
TILE_I = 64
kernel_mvt_opt = divide_loop(kernel_mvt_opt, "i #1", TILE_I, ["io", "ii"], tail="guard")

