            x1[i] += A[i, j] * y_1[j]

    # Second matrix-vector product: x2 += A^T * y_2
    # We iterate j outside and i inside so that we walk A[j, i] row-wise,
    # improving spatial locality in A and in x2.
    for j in seq(0, n):
        for i in seq(0, n):
            x2[i] += A[j, i] * y_2[j]


