from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable tile size for the second matrix-vector product (x2 update).
# This can be adjusted to better match the cache hierarchy of the target CPU.
TILE_I2 = 64


@proc
def kernel_mvt_impl(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # First matrix-vector multiply:
    #   x1[i] += sum_j A[i, j] * y_1[j]
    # Use a scalar accumulator so x1[i] is loaded and stored only once.
    for i in seq(0, n):
        acc1: DATA_TYPE
        acc1 = x1[i]
        for j in seq(0, n):
            acc1 += A[i, j] * y_1[j]
        x1[i] = acc1

    # Second matrix-vector multiply:
    #   x2[i] += sum_j A[j, i] * y_2[j]
    # We start from the straightforward i,j nest and improve its
    # data locality and parallelism using scheduling primitives below.
    for i in seq(0, n):
        for j in seq(0, n):
            x2[i] = x2[i] + A[j, i] * y_2[j]


# ---------------------------------------------------------------------------
# Scheduling: transform kernel_mvt_impl into an optimized kernel_mvt.
# ---------------------------------------------------------------------------

p = kernel_mvt_impl

# 1) Parallelize the outer loop of the first GEMV (x1 update).
#    Each iteration writes to a distinct x1[i], so this is embarrassingly
#    parallel and safe to annotate as a parallel loop.
p = parallelize_loop(p, "i #0")

# 2) Optimize the second GEMV (x2 update).
#    - Tile the i-dimension by TILE_I2.
#    - Reorder loops so that, inside each tile, we iterate over j first
#      and then the intra-tile i index. This yields contiguous accesses
#      to both A[j, i] (along the i dimension) and x2[i] within a tile.
#    - Parallelize across tiles of the i-dimension.
p = divide_loop(p, "i #1", TILE_I2, ["io2", "ii2"], tail="guard")
p = reorder_loops(p, "ii2 j")
p = parallelize_loop(p, "io2")

# 3) Simplify the resulting code to clean up index arithmetic and guards.
p = simplify(p)

# 4) Expose the final scheduled kernel under the name expected by the C code.
kernel_mvt = rename(p, "kernel_mvt")
EXO END
